      mojo::internal::GetArrayValidator<0, false, nullptr>();
  mojo::internal::Serialize<mojo::ArrayDataView<::arc::mojom::BootProgressEventDataView>>(
      in_events, events_fragment, &events_validate_params);
  params->events.Set(
      events_fragment.is_null() ? nullptr : events_fragment.data());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      params->events.is_null(),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
      "null events in MetricsHost.ReportBootProgress request");
