MetricsInstanceAsyncWaiter::MetricsInstanceAsyncWaiter(
    MetricsInstance* proxy) : proxy_(proxy) {}

MetricsInstanceAsyncWaiter::~MetricsInstanceAsyncWaiter() = default;

void MetricsInstanceAsyncWaiter::Init(
    ::mojo::PendingRemote<MetricsHost> host_remote) {
  base::RunLoop loop;
  proxy_->Init(std::move(host_remote),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



void MetricsInstanceAsyncWaiter::GetGfxMetrics(
    const std::string& packageName, GfxMetricsPtr* out_metrics) {
  base::RunLoop loop;
  proxy_->GetGfxMetrics(std::move(packageName),
      base::BindOnce(
          [](base::RunLoop* loop,
             GfxMetricsPtr* out_metrics
,
             GfxMetricsPtr metrics) {*out_metrics = std::move(metrics);
            loop->Quit();
          },
          &loop,
          out_metrics));
  loop.Run();
}

GfxMetricsPtr MetricsInstanceAsyncWaiter::GetGfxMetrics(
    const std::string& packageName) {
  GfxMetricsPtr async_wait_result;
  GetGfxMetrics(std::move(packageName),&async_wait_result);
  return async_wait_result;
}






